<script setup lang="ts">import type { ChannelMode, EmotionLabel, EmotionResult } from '../../core/models';
import { CHANNEL_MODE_LABELS } from '../../core/channel-fusion';
defineProps<{result:EmotionResult;modes:ChannelMode[];mode:ChannelMode;analyzedMode:ChannelMode;analyzing:boolean;analyzeError:string;stale:boolean;perChannelRms:number[];energyShare:number[];switchCount:number}>();
const emit=defineEmits<{select:[e:EmotionLabel];next:[];reanalyze:[];updateMode:[m:ChannelMode]}>();
const labels:EmotionLabel[]=['暴躁老哥','温柔姐姐','阴阳怪气','元气满满'];
const pct=(n:number)=>`${Math.round(n*100)}%`;</script>
<template><section class="stage-card"><span class="kicker">03 / MOOD MATCH</span><h2>这段声音，有点像——</h2>
<div class="channel-pick" role="group" aria-label="情绪分析声道口径"><span class="channel-pick-label">分析口径</span><div v-for="option in modes" :key="option"><input type="radio" name="channel-mode-emotion" :id="`channel-mode-emotion-${option}`" :value="option" :checked="mode===option" @change="emit('updateMode',option)"><label :for="`channel-mode-emotion-${option}`">{{ CHANNEL_MODE_LABELS[option] }}</label></div></div>
<div v-if="stale" class="stale-banner" data-testid="stale-banner">口径已从「{{ CHANNEL_MODE_LABELS[analyzedMode] }}」切换为「{{ CHANNEL_MODE_LABELS[mode] }}」。下方仍是旧口径结果，不能代表新口径，<button type="button" data-testid="reanalyze" :disabled="analyzing" @click="emit('reanalyze')">{{ analyzing ? '分析中…' : '用新口径重新分析' }}</button></div>
<div v-if="analyzeError" class="inline-error" data-testid="analyze-error">{{ analyzeError }}<button type="button" data-testid="retry-analyze" :disabled="analyzing" @click="emit('reanalyze')">{{ analyzing ? '分析中…' : '重试分析' }}</button></div>
<div v-if="!stale" class="fusion-readout" data-testid="fusion-readout"><span>左声道能量 {{ pct(perChannelRms[0] ?? 0) }}<i v-if="energyShare.length===2">汇合权重 {{ pct(energyShare[0] ?? 0) }}</i></span><span>右声道能量 {{ pct(perChannelRms[1] ?? 0) }}<i v-if="energyShare.length===2">汇合权重 {{ pct(energyShare[1] ?? 0) }}</i></span><span v-if="mode==='both'">主导声道切换 {{ switchCount }} 次<i>逐帧按能量跟随说话侧</i></span><small>汇合按帧能量权重计算：反相不抵消，静音侧不稀释。</small></div>
<div class="emotion-hero" :class="{faded:stale}"><b>{{ result.label }}</b><strong>{{ Math.round(result.confidence*100) }}%</strong><p>{{ result.explanation }}</p></div><div class="emotion-options"><button v-for="label in labels" :key="label" type="button" :data-emotion="label" :class="{active:result.label===label}" :disabled="stale" @click="emit('select',label)">{{ label }}</button></div><button data-testid="to-cover" class="acid-button" type="button" :disabled="stale" @click="emit('next')">用这个情绪做封面 →</button></section></template>
